import itertools

def find_all_interval_series(n):
    for perm in itertools.permutations(range(n)):
        diffs = [abs(perm[i+1] - perm[i]) for i in range(n-1)]
        if set(diffs) == set(range(1, n)):
            return perm
    return None

sol = find_all_interval_series(9)
print(sol)
